// DOM only. Draws "I feel different": the choice of symptom, then the episode in the order data, gaps, suggestion, and its actions.
// Native controls only. The summary is generated by one button and shared by another that needs a confirmation checkbox.
import {renderSection} from '../base/index.js';

export function mount(element, viewModel) {
  const doc = element.ownerDocument;
  let current = viewModel;
  const state = {symptom: '', confirmed: false, execution: '', task: ''};
  const el = (tag, attrs = {}, ...children) => {
    const node = doc.createElement(tag);
    for (const [name, value] of Object.entries(attrs)) node.setAttribute(name, String(value));
    for (const child of children) if (child !== null && child !== undefined) node.append(typeof child === 'object' ? child : doc.createTextNode(String(child)));
    return node;
  };
  const sectionOf = id => current.sections.find(section => section.id === id);
  const button = (id, label, enabled, handler) => { const b = el('button', {type: 'button', id}, label); if (!enabled) b.setAttribute('disabled', 'disabled'); b.addEventListener('click', handler); return b; };
  const select = (id, label, options, key, blank) => {
    const control = el('select', {id}, el('option', {value: ''}, blank), ...options.map(option => el('option', {value: option.id}, option.label))); control.value = state[key];
    control.addEventListener('change', () => { state[key] = control.value; });
    return el('div', {class: 'field'}, el('label', {for: id}, label), control);
  };

  async function apply(work, focusId) {
    current = await work;
    draw();
    const back = doc.getElementById(focusId) ?? doc.getElementById('feel-message');
    if (back) { if (back.tagName === 'P' && !back.hasAttribute('tabindex')) back.setAttribute('tabindex', '-1'); back.focus(); }
  }

  function start(section) {
    if (section.state !== 'ready') return renderSection(doc, section);
    const form = el('form', {id: 'feel-form'}, select('feel-symptom', 'Symptom', section.options, 'symptom', 'Choose one'), el('button', {type: 'submit', id: 'feel-open'}, 'Record and open an episode'));
    if (!section.actions.open.enabled) form.querySelector('button').setAttribute('disabled', 'disabled');
    form.addEventListener('submit', event => { event.preventDefault(); apply(current.interactions.open(state.symptom).then(next => { if (next.message && next.message.kind === 'info') state.symptom = ''; return next; }), 'feel-open'); });
    return el('section', {class: 'card', 'aria-labelledby': 'sec-start'}, el('h3', {id: 'sec-start'}, section.title), el('p', {class: 'legend'}, section.note), form,
      el('p', {class: 'legend'}, 'In a hurry? You can ask for help without choosing anything.'), button('feel-help', 'Ask for help now', section.actions.help.enabled, () => apply(current.interactions.askHelp(), 'feel-help')),
      section.actions.open.enabled ? null : el('p', {class: 'notice notice-info'}, section.actions.open.reason));
  }

  function suggestion(section) {
    const parts = [el('h3', {id: 'sec-suggestion'}, section.title), el('p', {class: 'legend'}, section.note)];
    if (section.suggestion) parts.push(el('p', {}, section.suggestion.text), el('p', {class: 'legend'}, `Source: ${section.suggestion.source_text}`), section.suggestion.caution ? el('p', {class: 'notice notice-warning'}, section.suggestion.caution) : null);
    else parts.push(el('p', {class: 'notice notice-info'}, section.text));
    parts.push(el('details', {class: 'table-toggle'}, el('summary', {}, 'What was not looked at'), el('ul', {}, ...section.not_assessed.map(text => el('li', {}, text)))));
    if (section.alert) parts.push(el('p', {class: 'notice notice-warning', role: 'alert'}, section.alert.text), button('feel-ack', 'Mark the alert as issued', current.actions.close.enabled, () => apply(current.interactions.acknowledgeAlert(), 'feel-ack')));
    return el('section', {class: 'card', 'aria-labelledby': 'sec-suggestion'}, ...parts);
  }

  function linkCard(section) {
    const form = el('form', {id: 'feel-link-form'}, select('feel-link-exec', 'An execution', section.executions, 'execution', 'None'), select('feel-link-task', 'A pending task', section.tasks, 'task', 'None'), el('button', {type: 'submit', id: 'feel-link'}, 'Link'));
    if (!current.actions.close.enabled) form.querySelector('button').setAttribute('disabled', 'disabled');
    form.addEventListener('submit', event => {
      event.preventDefault();
      const input = {}; if (state.execution) input.execution_id = state.execution; if (state.task) input.task_id = state.task;
      apply(current.interactions.link(input).then(next => { if (next.message && next.message.kind === 'info') { state.execution = ''; state.task = ''; } return next; }), 'feel-link');
    });
    return el('section', {class: 'card', 'aria-labelledby': 'sec-link'}, el('h3', {id: 'sec-link'}, section.title), form);
  }

  function actions() {
    const confirm = el('input', {type: 'checkbox', id: 'feel-confirm'}); confirm.checked = state.confirmed; confirm.addEventListener('change', () => { state.confirmed = confirm.checked; });
    const share = button('feel-share', 'Share with the ground panel', current.actions.share.enabled, () => apply(current.interactions.shareWithGround({confirmed: state.confirmed}).then(next => { if (next.message && next.message.kind === 'info') state.confirmed = false; return next; }), 'feel-share'));
    const parts = [el('h3', {id: 'sec-actions'}, 'Summary and sharing'), el('p', {class: 'legend'}, 'Generating a summary sends nothing. Sharing is a separate step.'),
      button('feel-summary', 'Generate summary', current.actions.close.enabled, () => apply(current.interactions.generateSummary(), 'feel-summary'))];
    const summary = sectionOf('summary');
    if (summary) parts.push(el('h4', {}, summary.title), el('pre', {id: 'feel-summary-text', tabindex: '0', class: 'summary-text'}, summary.text), el('p', {class: 'legend'}, summary.note));
    parts.push(el('div', {class: 'field'}, confirm, ' ', el('label', {for: 'feel-confirm'}, 'I confirm I want to send this episode\'s records to the ground panel (simulated).')), share,
      current.actions.share.enabled ? null : el('p', {class: 'notice notice-info'}, current.actions.share.reason), button('feel-close', 'Close the episode', current.actions.close.enabled, () => apply(current.interactions.closeEpisode(), 'feel-close')));
    return el('section', {class: 'card', 'aria-labelledby': 'sec-actions'}, ...parts);
  }

  const reopenReasons = new Map();
  function historyCard(section) {
    const rows = section.items.map(item => {
      const why = el('input', {id: `feel-reopen-why-${item.id}`, type: 'text', maxlength: '500', autocomplete: 'off'}); why.value = reopenReasons.get(item.id) ?? ''; why.addEventListener('input', () => reopenReasons.set(item.id, why.value));
      const b = el('button', {type: 'button', id: `feel-reopen-${item.id}`}, 'Reopen this episode'); if (!item.reopen.enabled) b.setAttribute('disabled', 'disabled');
      b.addEventListener('click', () => apply(current.interactions.reopenEpisode(item.id, why.value).then(next => { if (next.message && next.message.kind === 'info') reopenReasons.delete(item.id); return next; }), b.id));
      return el('li', {class: 'entry'}, el('div', {}, item.text), el('div', {class: 'field'}, el('label', {for: why.id}, 'Why reopen it (needed)'), why), b, item.reopen.enabled ? null : el('p', {class: 'notice notice-info'}, item.reopen.reason));
    });
    return el('section', {class: 'card', 'aria-labelledby': 'sec-history'}, el('h3', {id: 'sec-history'}, section.title), el('ul', {class: 'entries'}, ...rows));
  }

  function draw() {
    const parts = [];
    if (current.message) parts.push(el('p', {id: 'feel-message', class: `notice notice-${current.message.kind === 'error' ? 'error' : 'info'}`, role: current.message.kind === 'error' ? 'alert' : 'status'}, current.message.text));
    for (const section of current.sections) {
      if (section.id === 'start') parts.push(start(section));
      else if (section.id === 'suggestion') parts.push(suggestion(section));
      else if (section.id === 'link') parts.push(linkCard(section));
      else if (section.id === 'history' && section.state === 'ready') parts.push(historyCard(section));
      else if (section.id === 'summary') continue;
      else parts.push(renderSection(doc, section));
    }
    if (current.actions && current.actions.close) parts.push(actions());
    element.replaceChildren(...parts);
  }
  draw();
}
